 "content": "def transform(grid):
    # Replace holes in the repeating color field. Its sequence is periodic
    # across columns, but skips color 2 except in the frame's seed row.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seq = [1, 3, 5, 7, 9]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                # Row phase is determined by other intact cells on that row.
                j = next(j for j in range(3, w) if grid[r][j] in seq)
                out[r][c] = seq[(seq.index(grid[r][j]) + c - j) % 5]
    return out
