 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = [1, 3, 5, 7, 9]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # Repeating diagonal field. Determine phase from the closest
            # intact cell on the same row; phase repeats every five columns.
            candidates = [j for j in range(w) if grid[r][j] in colors]
            if candidates:
                j = min(candidates, key=lambda x: abs(x-c))
                out[r][c] = colors[(colors.index(grid[r][j]) + c-j) % 5]
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = 1
    return out

